async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  const decoder = new TextDecoder("utf-8");
  let accepted = 0;
  let rejected = 0;
  let line = 1;
  let byteLength = 0;
  let parts = [];
  let eofObserved = false;
  let cancelled = false;

  async function cancelOnce() {
    if (!cancelled) {
      cancelled = true;
      await reader.cancel();
    }
  }

  async function visitCurrentLine() {
    const tail = decoder.decode();
    if (tail) parts.push(tail);

    let text = parts.join("");
    parts = [];
    byteLength = 0;

    if (text.endsWith("\r")) {
      text = text.slice(0, -1);
    }

    if (/^\s*$/.test(text)) {
      return true;
    }

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      rejected++;
      return true;
    }

    const result = await visitor({ line, value });
    accepted++;
    return result !== false;
  }

  try {
    while (true) {
      const record = await reader.read();

      if (record.done) {
        eofObserved = true;

        if (byteLength !== 0) {
          const shouldContinue = await visitCurrentLine();
          if (!shouldContinue) {
            return { accepted, rejected, stopped: true };
          }
        }

        return { accepted, rejected, stopped: false };
      }

      const chunk = record.value;
      let start = 0;

      for (let i = 0; i < chunk.length; i++) {
        if (chunk[i] !== 0x0a) continue;

        const segment = chunk.subarray(start, i);
        byteLength += segment.length;

        const decoded = decoder.decode(segment, { stream: true });
        if (decoded) parts.push(decoded);

        const shouldContinue = await visitCurrentLine();
        if (!shouldContinue) {
          await cancelOnce();
          return { accepted, rejected, stopped: true };
        }

        line++;
        start = i + 1;
      }

      if (start < chunk.length) {
        const segment = chunk.subarray(start);
        byteLength += segment.length;

        const decoded = decoder.decode(segment, { stream: true });
        if (decoded) parts.push(decoded);
      }
    }
  } catch (error) {
    await cancelOnce();
    throw error;
  } finally {
    reader.releaseLock();
  }
}
